# Generated by `cargo xtask formula` in michel-onstein/acs for each release
# (scripts/update-tap.sh): edit the generator there, not this file.
#
# acs releases are signed; SHA256SUMS.sig is checked against this key:
#   ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAILbxQW5C9X7CdwcQ4bab0gsQi4Evk2xfgmI/972dlHCb acs release signing
# Verify a release by hand:
#   printf 'releases@acs namespaces="acs-release" %s\n' "$key" > allowed
#   ssh-keygen -Y verify -f allowed -I releases@acs -n acs-release -s SHA256SUMS.sig < SHA256SUMS
class Acs < Formula
  desc "Persistent, reconnecting remote shells over ssh"
  homepage "https://github.com/michel-onstein/acs"
  license "MIT"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/michel-onstein/acs/releases/download/v0.16.0/acs-0.16.0-aarch64-apple-darwin.tar.gz"
      sha256 "6b4be8f7bfe445d1c813a16e4cada69a573bfe090c23548d20fa7447c0487d0c"
    end

    on_intel do
      url "https://github.com/michel-onstein/acs/releases/download/v0.16.0/acs-0.16.0-x86_64-apple-darwin.tar.gz"
      sha256 "608253fdbe88829c88622238d494ced27ed276a02bd537a506e6bc3d4caf3254"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/michel-onstein/acs/releases/download/v0.16.0/acs-0.16.0-aarch64-unknown-linux-musl.tar.gz"
      sha256 "4f83253f4781b7ff6cf0785708accb365f3482b17016c6029bf25ae912cb560f"
    end

    on_intel do
      url "https://github.com/michel-onstein/acs/releases/download/v0.16.0/acs-0.16.0-x86_64-unknown-linux-musl.tar.gz"
      sha256 "046233d40063cf06cd9d0d654672ca265f822186a17f40cf4f7a47f6f90b0c35"
    end
  end

  def install
    bin.install "acs"
  end

  test do
    out = shell_output("#{bin}/acs --version")
    assert_match "acs #{version} ", out
    remotes = out[/^installs remotes: (.*)$/, 1].to_s.split(", ")
    assert_includes remotes, "x86_64-unknown-linux-musl"
    assert_includes remotes, "aarch64-unknown-linux-musl"
  end
end
